414	func configureCreateMirrors(ctx context.Context, outW, errW io.Writer, client *coreapi.Client, owner, repo, jurisdiction string, nonInteractive bool) ([]coreapi.ResolvedPlacement, error) {
415		regions, err := availableRegions(ctx, client)
416		if err != nil {
417			return nil, fmt.Errorf("list regions: %w", err)
418		}
419		if len(regions) == 0 {
420			return nil, errors.New("no regions available to mirror into")
421		}
422		selected, err := pickConfigureRegions(ctx, outW, regions, jurisdiction, nonInteractive)
423		if err != nil {
424			return nil, err
425		}
426		results := createMirrors(ctx, errW, mirrorTargets([]coreapi.AvailableMirror{{Owner: owner, Repo: repo}}, selected), false, 30*time.Minute)
427		reportErr := reportMirrorResults(outW, errW, results)
428		placements := configureSuccessfulMirrorPlacements(selected, results)
429		if len(placements) > 0 {
430			if reportErr != nil {
431				fmt.Fprintf(errW, "Continuing with %d mirror(s) that succeeded.\n", len(placements))
432			}
433			return placements, nil
434		}
435		if reportErr != nil {
436			return nil, reportErr
437		}
438		return nil, errors.New("no usable mirrors were created")
439	}
