457	func pickConfigureRegions(ctx context.Context, outW io.Writer, regions []regionChoice, jurisdiction string, nonInteractive bool) ([]regionChoice, error) {
458		opts, defaults := clusterChoices(regions, jurisdiction)
459		byHost := make(map[string]regionChoice, len(regions))
460		for _, region := range regions {
461			byHost[region.host] = region
462		}
463		selected := append([]string(nil), defaults...)
464		if nonInteractive {
465			if len(selected) == 0 && len(opts) > 0 {
466				selected = append(selected, opts[0].Value)
467			}
468			chosen := make([]regionChoice, 0, len(selected))
469			for _, host := range selected {
470				if region, ok := byHost[host]; ok {
471					chosen = append(chosen, region)
472				}
473			}
474			return chosen, nil
475		}
476		form := NewAccessibleForm(huh.NewGroup(
477			huh.NewMultiSelect[string]().
478				Title("Which regions should this repository live in?").
479				Description("Space to select, enter to confirm — your data stays in the selected regions.").
480				Options(opts...).
481				Height(multiSelectHeight(len(opts))).
482				Validate(func(values []string) error {
483					if len(values) == 0 {
484						return errors.New("select at least one region")
485					}
486					return nil
487				}).
488				Value(&selected),
489		))
490		if err := form.RunWithContext(ctx); err != nil {
491			if cancelErr := handleFormCancellation(outW, "Configure", err); cancelErr != nil {
492				return nil, cancelErr
493			}
494			return nil, NewSilentError(errors.New("configure cancelled"))
495		}
496		chosen := make([]regionChoice, 0, len(selected))
497		for _, host := range selected {
498			if region, ok := byHost[host]; ok {
499				chosen = append(chosen, region)
500			}
501		}
502		return chosen, nil
503	}
