673	func sameStrings(a, b []string) bool {
674		if len(a) != len(b) {
675			return false
676		}
677		seen := make(map[string]int, len(a))
678		for _, value := range a {
679			seen[value]++
680		}
681		for _, value := range b {
682			seen[value]--
683			if seen[value] < 0 {
684				return false
685			}
686		}
687		return true
688	}
