1181		return huh.ThemeFunc(func(isDark bool) *huh.Styles {
1182			theme := uiform.Theme().Theme(isDark)
1183			success := lipgloss.Color(palette.Success)
1184			muted := lipgloss.Color(palette.Muted)
1185	
1186			// Radio and checkbox lists use the same active-row indicator. Selection
1187			// remains green and independent from the orange `>` cursor.
1188			theme.FieldSeparator = lipgloss.NewStyle().SetString("")
1189			theme.Focused.Base = lipgloss.NewStyle()
1190			theme.Blurred.Base = lipgloss.NewStyle()
1191			theme.Focused.SelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1192			theme.Blurred.SelectSelector = lipgloss.NewStyle().SetString("  ")
1193			theme.Focused.MultiSelectSelector = lipgloss.NewStyle().Foreground(lipgloss.Color(palette.Warning)).SetString("> ")
1194			theme.Blurred.MultiSelectSelector = lipgloss.NewStyle().SetString("  ")
1195			theme.Focused.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
1196			theme.Blurred.SelectedPrefix = lipgloss.NewStyle().Foreground(success).SetString("◼ ")
1197			theme.Focused.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
1198			theme.Blurred.UnselectedPrefix = lipgloss.NewStyle().Foreground(muted).SetString("◻ ")
1199			theme.Focused.SelectedOption = theme.Focused.SelectedOption.UnsetForeground()
1200			theme.Blurred.SelectedOption = theme.Blurred.SelectedOption.UnsetForeground()
1201			// Enabled options keep normal text contrast whether selected or not.
1202			// Muting the empty checkbox is sufficient; muting the label itself can
1203			// incorrectly communicate that the option is disabled.
1204			theme.Focused.UnselectedOption = theme.Focused.UnselectedOption.UnsetForeground()
1205			theme.Blurred.UnselectedOption = theme.Blurred.UnselectedOption.UnsetForeground()
1206			return theme
1207		})
1208	}
1209	
1210	func configureQuestionTitle(question string, focused bool) string {
1211		color := palette.Muted
1212		if focused {
1213			color = palette.Warning
1214		}
1215		marker := lipgloss.NewStyle().Foreground(lipgloss.Color(color)).Render("?")
1216		heading := lipgloss.NewStyle().Bold(true).Render(question)
1217		return marker + " " + heading
