1220	func configureAgentOptions(options []huh.Option[string], selected map[types.AgentName]struct{}) []huh.Option[string] {
1221		plain := make([]huh.Option[string], 0, len(options))
1222		for _, option := range options {
1223			item := huh.NewOption(option.Key, option.Value)
1224			if _, ok := selected[types.AgentName(option.Value)]; ok {
1225				item = item.Selected(true)
1226			}
1227			plain = append(plain, item)
1228		}
