1232	func configureCurrentUpstream(ctx context.Context, repoRoot string) string {
1233		raw, err := gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1234		if err != nil {
1235			return ""
1236		}
1237		info, err := gitremote.ParseURL(raw)
1238		if err != nil || info.Protocol != gitremote.ProtocolEntire {
1239			return ""
1240		}
1241		return info.Host
1242	}
1243	
1244	func configurePlacementOrder(placements []coreapi.ResolvedPlacement, currentHost, jurisdiction string) []coreapi.ResolvedPlacement {
1245		ordered := append([]coreapi.ResolvedPlacement(nil), placements...)
1246		sort.SliceStable(ordered, func(i, j int) bool {
1247			iCurrent := strings.EqualFold(ordered[i].ClusterHost, currentHost)
1248			jCurrent := strings.EqualFold(ordered[j].ClusterHost, currentHost)
1249			if iCurrent != jCurrent {
1250				return iCurrent
1251			}
1252			iHome := strings.EqualFold(ordered[i].Jurisdiction.Or(""), jurisdiction)
1253			jHome := strings.EqualFold(ordered[j].Jurisdiction.Or(""), jurisdiction)
1254			if currentHost == "" && iHome != jHome {
1255				return iHome
1256			}
1257			return configurePlacementLabel(ordered[i]) < configurePlacementLabel(ordered[j])
1258		})
1259		return ordered
1260	}
