1262	func configurePlacementLabel(placement coreapi.ResolvedPlacement) string {
1263		if jurisdiction := strings.ToLower(strings.TrimSpace(placement.Jurisdiction.Or(""))); jurisdiction != "" {
1264			if name, ok := configureJurisdictionNames[jurisdiction]; ok {
1265				return name
1266			}
1267			return strings.ToUpper(jurisdiction)
1268		}
1269		if cell := strings.TrimSpace(placement.Cell.Or("")); cell != "" {
1270			return cell
1271		}
1272		return placement.ClusterHost
1273	}
1274	
1275	var configureJurisdictionNames = map[string]string{ //nolint:gochecknoglobals // immutable display-name lookup
1276		"au": "Australia",
1277		"eu": "European Union",
1278		"in": "India",
1279		"us": "United States",
1280	}
1281	
1282	func configureAgentPreselection(ctx context.Context) map[types.AgentName]struct{} {
1283		selected := make(map[types.AgentName]struct{})
1284		if installed := GetAgentsWithHooksInstalled(ctx); len(installed) > 0 {
1285			for _, name := range installed {
1286				selected[name] = struct{}{}
1287			}
1288			return selected
1289		}
1290		for _, detected := range agent.DetectAll(ctx) {
1291			if isBuiltInAgent(detected) {
1292				selected[detected.Name()] = struct{}{}
1293			}
1294		}
1295		return selected
1296	}
1297	
1298	func configureUseMirror(ctx context.Context, outW, errW io.Writer, repoRoot, owner, repo string, chosen coreapi.ResolvedPlacement) (string, error) {
1299		remotes, err := listGitRemotes(ctx, repoRoot)
1300		if err != nil {
1301			return "", err
1302		}
1303		current := ""
1304		if remotes[defaultMirrorRemote] {
1305			current, err = gitremote.GetRemoteURLInDir(ctx, repoRoot, defaultMirrorRemote)
1306			if err != nil {
1307				return "", fmt.Errorf("read origin remote URL: %w", err)
1308			}
1309		}
1310	
1311		forgeRemote, err := configureExistingForgeRemote(ctx, repoRoot, owner, repo, remotes, defaultMirrorRemote)
1312		if err != nil {
1313			return "", err
1314		}
1315		preserve := ""
1316		if info, parseErr := gitremote.ParseURL(current); parseErr == nil && info.Protocol != gitremote.ProtocolEntire {
1317			if forgeRemote == "" {
1318				preserve = availableConfigureRemoteName(remotes, defaultMirrorUpstreamRemote, mirrorCloneProviderGitHub)
1319				forgeRemote = preserve
1320			}
1321		}
1322		if forgeRemote == "" {
1323			forgeRemote = availableConfigureRemoteName(remotes, mirrorCloneProviderGitHub)
1324			forgeURL := configureGitHubForgeURL(ctx, owner, repo)
1325			if _, err := gitRunner(ctx, repoRoot, "remote", "add", forgeRemote, forgeURL); err != nil {
1326				return "", fmt.Errorf("add GitHub push remote %q: %w", forgeRemote, err)
1327			}
1328			remotes[forgeRemote] = true
1329			fmt.Fprintf(outW, "✓ Added GitHub push remote %q\n  %s\n", forgeRemote, forgeURL)
1330		}
1331	
1332		mirrorURL := mirrorCloneURL(chosen.ClusterHost, owner, repo)
1333		plan := planMirrorRemote(defaultMirrorRemote, mirrorURL, current, preserve, remotes)
1334		if err := applyMirrorRemotePlan(ctx, repoRoot, plan); err != nil {
1335			return "", err
1336		}
1337		if err := configureRetargetCurrentBranch(ctx, repoRoot, forgeRemote); err != nil {
1338			return "", err
1339		}
1340		// Report the replaced URL and where it remains reachable. The returned
1341		// forgeRemote is deliberately separate from the mirror fetch remote: config
1342		// commits must land on GitHub, never in the one-way Entire mirror.

